#!/usr/bin/env bash
#
# PocketPills — recover ALL medicines from handwritten prescriptions (v3).
# Applies on top of commit 86eb3eb.
#
# ROOT CAUSE (measured on the real prescription-demo.webp pixels, not guessed):
# segmentation split ROWS first and COLUMNS second. On a two-column page the
# left column's ink (BP, SpO2, Diet) bridges every gap in the right column, so
# all five medicines fused into ONE 492px crop. TrOCR reads only the first line
# of whatever it is given, so three medicines never existed downstream.
#
#  1. lineSegments.ts — rows -> columns -> rows AGAIN inside each column cell,
#     plus valley-splitting for lines whose ascenders/descenders touch.
#     Verified: 5/5 medicines now land in their own crop (was 1 merged blob).
#     Also reverts the v2 page-level adaptive threshold, which measurement
#     showed made the merging WORSE.
#  2. trocrWorker.ts — n-best beam decoding (4 beams) instead of greedy, with
#     a graceful fallback if the runtime declines the options.
#  3. rxLexicon.ts + htrClient.ts — re-rank those candidates against the
#     formulary. This is the browser equivalent of the dictionary-constrained
#     CTC decoding that the CRNN/CTC projects recommend; greedy decoding is
#     unreliable for drug names, which are out-of-vocabulary for any
#     IAM-trained handwriting model.
#
# Debug any scan:  localStorage.setItem("pp:rx-debug","1")  then rescan.
# Safe to re-run. Backs up touched files; verifies with tsc + vite build.
#
set -euo pipefail

grep -q '"pocketpills-redesign"' package.json 2>/dev/null || {
  echo "!! Run from the pocketpills repo root."; exit 1; }

BK=".rxfix3-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "${BK}/src/lib/localHtr"
echo ">> Backups -> ${BK}/"
cp src/lib/rxOcr.ts src/lib/rxLexicon.ts "${BK}/src/lib/"
cp src/lib/localHtr/*.ts "${BK}/src/lib/localHtr/"

if grep -q "splitTallBands" src/lib/localHtr/lineSegments.ts; then
  echo ">> Already patched — skipping"
else
  echo ">> Patching segmentation + decoding + re-ranking"
  PATCH=""
  if printf '%s' "$PATCH" | base64 -d | git apply -p1 --check - 2>/dev/null; then
    printf '%s' "$PATCH" | base64 -d | git apply -p1 -; echo "   applied via git apply"
  elif printf '%s' "$PATCH" | base64 -d | patch -p1 --dry-run >/dev/null 2>&1; then
    printf '%s' "$PATCH" | base64 -d | patch -p1; echo "   applied via patch"
  else
    echo "!! Did not apply cleanly — your files differ from commit 86eb3eb."
    echo "   Backup at ${BK}."; exit 2
  fi
fi

echo ">> Verifying (tsc)"; npx tsc -b --noEmit
echo ">> Verifying (vite build)"; npx vite build >/dev/null
echo ""
echo "Done. Backup: ${BK}"
echo "Rollback: cp -r ${BK}/src ./"
